INSERT INTO zc_private.discord_user_preference (discord_id,ping_on_world_record_loss,date_updated) VALUES($1,$2,clock_timestamp()) ON CONFLICT(discord_id) DO UPDATE SET ping_on_world_record_loss=excluded.ping_on_world_record_loss, date_updated=clock_timestamp() RETURNING discord_id,ping_on_world_record_loss, to_char(date_updated AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS date_updated
